add(78,'철도를y=0(x≤0)에서y=1(x≥1)로잇는다. (a)0<x<1에서함수값·기울기·곡률이연속이되도록5차다항식P를구하고(b)연결함수F를그려라.','Join railway tracks y=0 for x≤0 and y=1 for x≥1. (a)Find a quintic P on0<x<1 giving continuous value, slope and curvature;(b)graph the joined function F.',[m(r'P(0)=0,\ P(1)=1,\ P^{\prime}(0)=P^{\prime}(1)=0'),'직선부분의곡률은0이다. 끝점기울기가0이므로곡률연속성은P″(0)=P″(1)=0이다.',m(r'P=ax^5+bx^4+cx^3,\quad a+b+c=1,\quad5a+4b+3c=0,\quad20a+12b+6c=0'),m(r'(a,b,c)=(6,-15,10),\quad P^{\prime}=30x^2(x-1)^2\ge0')],[m(r'P(0)=0,\ P(1)=1,\ P^{\prime}(0)=P^{\prime}(1)=0'),'The straight sections have zero curvature. With zero endpoint slopes, curvature continuity requires P″(0)=P″(1)=0.',m(r'P=ax^5+bx^4+cx^3,\quad a+b+c=1,\quad5a+4b+3c=0,\quad20a+12b+6c=0'),m(r'(a,b,c)=(6,-15,10),\quad P^{\prime}=30x^2(x-1)^2\ge0')],m(r'P(x)=6x^5-15x^4+10x^3,\quad F(x)=\begin{cases}0&x\le0\\P(x)&0<x<1\\1&x\ge1\end{cases}'),parts=list('ab'))
